antiPatterns.example:
// Avoid: Using PromptInput for forms
<PromptInput onSubmit={handleFormSubmit} />

// Prefer: Use appropriate form input components
<TextArea onChange={handleChange} />

// Avoid: Confusing users by disabling Enter
<PromptInput 
  onSubmit={handleSubmit}
  // Users expect Enter to submit
/>

// If you need different behavior, document it clearly

// Avoid: Validating in onSubmit
<PromptInput onSubmit={(value) => {
  if (!value) return; // Validate before
  sendMessage(value);
}} />

// Prefer: Disable button when empty
<PromptInput 
  onSubmit={sendMessage}
  disabled={!value}
/>
